import React from 'react';
import { ScrollView, StatusBar, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { MaterialDesignIconsIconName } from '@react-native-vector-icons/material-design-icons/static';
import { AppIcon } from '../ui/AppIcon';

type Props = {
  email: string;
  password: string;
  confirmPassword: string;
  locationName: string;
  code: string;
  error: string;
  isLoading: boolean;
  onEmailChange: (value: string) => void;
  onPasswordChange: (value: string) => void;
  onConfirmPasswordChange: (value: string) => void;
  onLocationChange: (value: string) => void;
  onCodeChange: (value: string) => void;
  onSubmit: () => void | Promise<void>;
};

function FormField({ icon, ...inputProps }: React.ComponentProps<typeof TextInput> & { icon: MaterialDesignIconsIconName }) {
  return (
    <View style={styles.inputShell}>
      <AppIcon name={icon} color="#64748B" size={21} />
      <TextInput {...inputProps} style={styles.input} placeholderTextColor="#94A3B8" />
    </View>
  );
}

export function SignupScreen({
  email,
  password,
  confirmPassword,
  locationName,
  code,
  error,
  isLoading,
  onEmailChange,
  onPasswordChange,
  onConfirmPasswordChange,
  onLocationChange,
  onCodeChange,
  onSubmit,
}: Props) {
  return (
    <SafeAreaView style={styles.safe}>
      <StatusBar barStyle="light-content" />
      <View style={styles.backgroundTop} />
      <View style={styles.backgroundBottom} />
      <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
        <View style={styles.hero}>
          <Text style={styles.title}>Create organization</Text>
          <Text style={styles.subtitle}>Set up your workspace, operator access, and sign-in credentials.</Text>
        </View>

        <View style={styles.card}>
          <FormField icon="office-building-outline" value={locationName} onChangeText={onLocationChange} placeholder="Organization name" />
          <FormField icon="identifier" value={code} onChangeText={onCodeChange} placeholder="Organization code" autoCapitalize="characters" />
          <FormField
            icon="email-outline"
            value={email}
            onChangeText={onEmailChange}
            placeholder="Contact email"
            autoCapitalize="none"
            keyboardType="email-address"
          />
          <FormField icon="lock-outline" value={password} onChangeText={onPasswordChange} placeholder="Password" secureTextEntry />
          <FormField
            icon="lock-check-outline"
            value={confirmPassword}
            onChangeText={onConfirmPasswordChange}
            placeholder="Confirm password"
            secureTextEntry
          />

          {!!error && (
            <View style={styles.errorBox}>
              <Text style={styles.errorText}>{error}</Text>
            </View>
          )}

          <TouchableOpacity style={[styles.button, isLoading ? styles.buttonDisabled : null]} onPress={onSubmit} disabled={isLoading} activeOpacity={0.9}>
            <Text style={styles.buttonText}>{isLoading ? 'Creating...' : 'Create account'}</Text>
            {!isLoading ? <View style={styles.buttonIcon}><AppIcon name="arrow-right" color="#FFFFFF" size={21} /></View> : null}
          </TouchableOpacity>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

