import React, { useMemo } from 'react';
import { ActivityIndicator, ScrollView, StatusBar, StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { AppIcon } from '../ui/AppIcon';
import { ReportRow, Ticket } from '../types';

type Props = {
  tickets: Ticket[];
  report?: {
    count: number;
    revenue: number;
  } | null;
  reportRows?: ReportRow[];
  truncated?: boolean;
  onBack: () => void;
  onExport?: () => void | Promise<void>;
  exporting?: boolean;
  exportError?: string;
};

export function ReportScreen({
  tickets,
  report,
  reportRows,
  truncated = false,
  onBack,
  onExport,
  exporting = false,
  exportError = '',
}: Props) {
  const totals = useMemo(() => {
    if (report) {
      return { count: report.count, amount: report.revenue };
    }
    const amount = tickets.reduce((sum, ticket) => sum + ticket.amount, 0);
    return { count: tickets.length, amount };
  }, [report, tickets]);
  const rows = reportRows ?? [];

  return (
    <SafeAreaView style={styles.safe}>
      <StatusBar barStyle="light-content" />
      <ScrollView contentContainerStyle={styles.container} showsVerticalScrollIndicator={false}>
        <Text style={styles.kicker}>Summary</Text>
        <Text style={styles.title}>Daily report</Text>
        <Text style={styles.subtitle}>Track each check-in and export every operational detail to Excel.</Text>

        <View style={styles.statsRow}>
          <Stat label="Tickets" value={`${totals.count}`} />
          <Stat label="Revenue" value={`Rs. ${totals.amount.toFixed(2)}`} />
        </View>

        <View style={styles.listCard}>
          {rows.map(row => (
            <View style={styles.reportRow} key={row.receiptNumber}>
              <View style={styles.ticketRow}>
                <View style={styles.ticketCopy}>
                  <Text style={styles.ticketNo}>{row.receiptNumber}</Text>
                  <Text style={styles.ticketMeta}>{row.vehicleNumber} · {row.vehicleType}</Text>
                </View>
                <Text style={styles.ticketAmount}>Parking fee{'\n'}Rs. {row.vehicleRate.toFixed(2)}</Text>
              </View>
              <Text style={styles.detail}>Barcode: {row.barcodeValue}</Text>
              <Text style={styles.organizationName}>{row.organizationName}</Text>
              <Text style={styles.detail}>Location: {row.locationName}</Text>
              <Text style={styles.detail}>Operator: {row.operatorName}</Text>
              <Text style={styles.detail}>Time: {new Date(row.issuedAt).toLocaleString()}</Text>
              <Text style={styles.detail}>Device GPS: {formatDeviceLocation(row)}</Text>
              <Text style={styles.detail}>Payment: {row.paymentMethod} · {row.paymentStatus}</Text>
              <Text style={styles.detail}>Print: {row.printStatus} · Sync: {row.syncStatus} · Reprints: {row.reprintCount}</Text>
            </View>
          ))}
          {rows.length === 0 && tickets.map(ticket => (
            <View style={styles.ticketRow} key={ticket.id}>
              <View style={styles.ticketCopy}>
                <Text style={styles.ticketNo}>{ticket.ticketNumber}</Text>
                <Text style={styles.ticketMeta}>{ticket.vehicleNumber}</Text>
              </View>
              <Text style={styles.ticketAmount}>Parking fee{'\n'}Rs. {ticket.amount.toFixed(2)}</Text>
            </View>
          ))}
          {rows.length === 0 && tickets.length === 0 && <Text style={styles.empty}>No tickets available.</Text>}
          {truncated ? <Text style={styles.warning}>Showing the first 500 receipts. Narrow the report period to see every record.</Text> : null}
        </View>

        {onExport ? (
          <TouchableOpacity
            accessibilityRole="button"
            accessibilityLabel="Export daily report as an Excel file"
            disabled={exporting}
            style={[styles.button, exporting && styles.buttonDisabled]}
            onPress={onExport}
            activeOpacity={0.9}
          >
            {exporting
              ? <ActivityIndicator color="#FFFFFF" size="small" />
              : <AppIcon name="microsoft-excel" color="#FFFFFF" size={22} />}
            <Text style={styles.buttonText}>{exporting ? 'Creating Excel file…' : 'Export Excel report'}</Text>
          </TouchableOpacity>
        ) : null}
        {exportError ? <Text accessibilityRole="alert" style={styles.exportError}>{exportError}</Text> : null}
        <TouchableOpacity style={styles.secondaryButton} onPress={onBack} activeOpacity={0.9}>
          <AppIcon name="arrow-left" color="#0F172A" size={21} />
          <Text style={styles.secondaryButtonText}>Back to home</Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <View style={styles.statCard}>
      <Text style={styles.statLabel}>{label}</Text>
      <Text style={styles.statValue}>{value}</Text>
    </View>
  );
}

function formatDeviceLocation(row: ReportRow) {
  if (!row.deviceLocation) return 'Not captured';
  const accuracy = row.deviceLocation.accuracy === undefined ? '' : ` ±${Math.round(row.deviceLocation.accuracy)}m`;
  const provider = row.deviceLocation.provider ? ` / ${row.deviceLocation.provider}` : '';
  return `${row.deviceLocation.latitude.toFixed(6)}, ${row.deviceLocation.longitude.toFixed(6)}${accuracy}${provider}`;
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: '#0F172A' },
  container: { paddingHorizontal: 20, paddingTop: 18, paddingBottom: 160, gap: 14 },
  kicker: { color: '#93C5FD', fontSize: 13, fontWeight: '700', textTransform: 'uppercase', letterSpacing: 0.8 },
  title: { color: '#FFFFFF', fontSize: 30, fontWeight: '900' },
  subtitle: { color: '#CBD5E1', fontSize: 15, lineHeight: 21 },
  statsRow: { flexDirection: 'row', gap: 12 },
  statCard: { flex: 1, backgroundColor: '#FFFFFF', borderRadius: 24, padding: 18 },
  statLabel: { color: '#64748B', fontSize: 13, fontWeight: '700', textTransform: 'uppercase' },
  statValue: { color: '#0F172A', fontSize: 20, fontWeight: '900', marginTop: 8 },
  listCard: {
    backgroundColor: '#FFFFFF',
    borderRadius: 30,
    padding: 16,
    shadowColor: '#020617',
    shadowOpacity: 0.16,
    shadowRadius: 24,
    shadowOffset: { width: 0, height: 16 },
    elevation: 6,
  },
  ticketRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: '#E2E8F0' },
  reportRow: { paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: '#E2E8F0' },
  ticketCopy: { flex: 1, minWidth: 0, flexShrink: 1 },
  ticketNo: { fontSize: 16, lineHeight: 21, fontWeight: '800', color: '#0F172A' },
  ticketMeta: { fontSize: 13, color: '#64748B', marginTop: 4 },
  ticketAmount: { flex: 1, flexShrink: 1, minWidth: 0, fontSize: 13, lineHeight: 18, fontWeight: '800', color: '#2563EB', textAlign: 'right' },
  organizationName: { fontSize: 12, lineHeight: 17, color: '#0F172A', marginTop: 6, fontWeight: '800' },
  detail: { fontSize: 12, lineHeight: 17, color: '#475569', marginTop: 3 },
  warning: { color: '#B45309', backgroundColor: '#FFFBEB', padding: 12, borderRadius: 12, marginTop: 12 },
  empty: { color: '#64748B', paddingVertical: 20, textAlign: 'center' },
  button: { minHeight: 56, flexDirection: 'row', gap: 9, backgroundColor: '#2563EB', borderRadius: 18, alignItems: 'center', justifyContent: 'center' },
  buttonDisabled: { opacity: 0.72 },
  buttonText: { color: '#FFFFFF', fontWeight: '800', fontSize: 17 },
  exportError: { color: '#B91C1C', backgroundColor: '#FEF2F2', padding: 12, borderRadius: 12, fontWeight: '600' },
  secondaryButton: {
    backgroundColor: '#FFFFFF',
    borderRadius: 18,
    minHeight: 56,
    flexDirection: 'row',
    gap: 9,
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 1,
    borderColor: '#CBD5E1',
  },
  secondaryButtonText: { color: '#0F172A', fontWeight: '800', fontSize: 17 },
});
